-- =====================================================================
-- EP WONNA — seed data
--
-- Run this ONCE after schema.sql, also in the SQL Editor. Adds exactly
-- one demo пробник per exam (EPM / EPD / EPE), per the brief — delete
-- them from the admin panel whenever real content is ready to replace
-- them; nothing else depends on these specific ids.
--
-- Together the three tests' questions cover all five question types
-- (multiple_choice, numeric, true_false, heading_match, free_text), so
-- this also doubles as a smoke test that the grading pipeline works
-- against real Supabase data, not just the old in-memory mock.
-- =====================================================================

-- ---- EPM: multiple_choice + numeric -----------------------------------
insert into public.tests
  (id, exam_key, title, short_description, full_description, is_official, topic, format, year, duration_minutes)
values
  ('epm-demo-1', 'epm', 'Демо-пробник по математике',
   'Тестовый пробник для проверки интеграции с базой данных.',
   'Демонстрационный пробник, добавленный при первом подключении к Supabase. Замените его настоящим содержимым через админ-панель.',
   true, 'algebra', null, 2026, 60)
on conflict (id) do nothing;

insert into public.questions (id, test_id, position, category, type, text, options, correct_option_ids)
