-- A real multi-part exam question ("Teil A, Aufgabe 1" from the person's
-- sample): one shared stem, part a) a fillable contingency table (some
-- cells given in the text, the rest computed by the student), part b)
-- four independent percentage questions. See the `multi_part` /
-- `table` type notes in src/utils/grading.js and schema.sql.
insert into public.questions (id, test_id, position, category, type, text, parts)
values
  ('epm-demo-1-q3', 'epm-demo-1', 3, 'Часть А', 'multi_part',
   'Eine Firma kauft bei zwei verschiedenen Anbietern A und B insgesamt 5400 Mikrochips ein. 60% der Mikrochips stammen vom Anbieter A, davon sind 95% in Ordnung. Von den Mikrochips des Anbieters B sind 270 defekt.',
   '[
     {
       "id": "a",
       "label": "a) Stellen Sie die Situation durch eine Tabelle dar!",
       "type": "table",
       "table": {
         "columns": ["Anbieter A", "Anbieter B", "Gesamt"],
         "rows": ["in Ordnung", "defekt", "Gesamt"],
         "cells": [
           [ { "correctValue": 3078, "tolerance": 1 }, { "correctValue": 1890, "tolerance": 1 }, { "correctValue": 4968, "tolerance": 1 } ],
           [ { "correctValue": 162,  "tolerance": 1 }, { "given": 270 },                          { "correctValue": 432,  "tolerance": 1 } ],
           [ { "correctValue": 3240, "tolerance": 1 }, { "correctValue": 2160, "tolerance": 1 },  { "given": 5400 } ]
         ]
       }
     },
     { "id": "b-i",   "label": "b) i. ein zufällig ausgewählter Mikrochip defekt ist?",                          "type": "numeric", "correctValue": 8,    "tolerance": 0.5, "unit": "%" },
     { "id": "b-ii",  "label": "b) ii. ein zufällig ausgewählter Mikrochip vom Anbieter B stammt und in Ordnung ist?", "type": "numeric", "correctValue": 35,   "tolerance": 0.5, "unit": "%" },
     { "id": "b-iii", "label": "b) iii. ein Mikrochip des Anbieters B in Ordnung ist?",                          "type": "numeric", "correctValue": 87.5, "tolerance": 0.5, "unit": "%" },
     { "id": "b-iv",  "label": "b) iv. ein defekter Mikrochip vom Anbieter A stammt?",                           "type": "numeric", "correctValue": 37.5, "tolerance": 0.5, "unit": "%" }
   ]'::jsonb)
on conflict (id) do nothing;

