-- Teil A, Aufgabe 1: triangular density function — a) find h so f is a
-- valid density, b) five probabilities, c) the piecewise formula itself
-- (free text — not a single number), d) the expected value E(x).
insert into public.questions (id, test_id, position, category, type, text, image, parts)
values
  ('epm-abschluss-2-q1', 'epm-abschluss-2', 1, 'Часть А', 'multi_part',
   'Die Wahrscheinlichkeit für das Eintreffen der Professorin in ihrer Vorlesung sei durch den Graphen der Dichtefunktion f gegeben.',
   'density-triangle',
   '[
     { "id": "a",    "label": "a) Bestimmen Sie die Höhe h des Dreiecks so, dass f(x) eine Dichtefunktion ist!", "type": "numeric", "correctValue": 0.4, "tolerance": 0.01 },
     { "id": "b-i",  "label": "b) i. genau zum Beginn der Stunde kommt (x = 0)",                                  "type": "numeric", "correctValue": 0,   "tolerance": 0.01 },
     { "id": "b-ii", "label": "b) ii. nach dem Beginn der Vorlesung eintrifft (x > 0)",                           "type": "numeric", "correctValue": 0.8, "tolerance": 0.01 },
     { "id": "b-iii","label": "b) iii. zu früh kommt (x < 0)",                                                    "type": "numeric", "correctValue": 0.2, "tolerance": 0.01 },
     { "id": "b-iv", "label": "b) iv. um mindestens 2 Minuten zu spät kommt",                                     "type": "numeric", "correctValue": 0.2, "tolerance": 0.01 },
     { "id": "b-v",  "label": "b) v. um mindestens 2 Minuten zu spät kommt unter der Bedingung, dass sie zu spät kommt", "type": "numeric", "correctValue": 0.25, "tolerance": 0.01 },
     { "id": "c",    "label": "c) Bestimmen Sie den Funktionsterm von f! (Geben Sie f(x) für −1 < x ≤ 0, 0 < x ≤ 4 und sonst an.)", "type": "free_text" },
     { "id": "d",    "label": "d) Berechnen Sie den Erwartungswert E(x) für das Eintreffen der Professorin!",     "type": "numeric", "correctValue": 1.0, "tolerance": 0.05, "unit": "мин" }
   ]'::jsonb)
on conflict (id) do nothing;

-- Teil A, Aufgabe 2: quadrilateral ABCD — split by diagonal AC (law of
-- cosines in triangle ACD, then law of sines in both triangles) to find
-- BC. Answer verified numerically: BC ≈ 72.7 mm.
insert into public.questions (id, test_id, position, category, type, text, correct_value, tolerance, unit)
values
  ('epm-abschluss-2-q2', 'epm-abschluss-2', 2, 'Часть А', 'numeric',
   'Von einem Viereck ABCD kennt man die Längen CD = 94,2 mm und DA = 107,5 mm und die Winkel α = ∢DAB = 61,8°, γ = ∢BCD = 96,7° und δ = ∢CDA = 104,3°. Berechnen Sie die Länge der Seite BC! (Runden Sie auf die erste Nachkommastelle.)',
   72.7, 0.1, 'mm')
on conflict (id) do nothing;

-- Teil A, Aufgabe 3: plane + line in R³ — normal form, line equation,
-- intersection point + angle, normal distance, and a point at a given
-- distance (infinitely many valid answers, so that last part is free text).
insert into public.questions (id, test_id, position, category, type, text, parts)
values
  ('epm-abschluss-2-q3', 'epm-abschluss-2', 3, 'Часть А', 'multi_part',
   'Gegeben sind die Ebene ε: X = (7|1|0) + k·(3|0|−1) + ℓ·(6|2|1) und die Punkte P(−10|4|5) und Q(0|−1|20).',
   '[{"id": "a", "label": "a) Geben Sie eine Gleichung der Ebene ε in Normalform an!", "type": "free_text"}, {"id": "b", "label": "b) Geben Sie eine Gleichung der Geraden g[P,Q] durch die Punkte P und Q an!", "type": "free_text"}, {"id": "c-i-x", "label": "c) i. Schnittpunkt — x-Koordinate", "type": "numeric", "correctValue": -8, "tolerance": 0.01}, {"id": "c-i-y", "label": "c) i. Schnittpunkt — y-Koordinate", "type": "numeric", "correctValue": 3, "tolerance": 0.01}, {"id": "c-i-z", "label": "c) i. Schnittpunkt — z-Koordinate", "type": "numeric", "correctValue": 8, "tolerance": 0.01}, {"id": "c-ii", "label": "c) ii. Schnittwinkel ∢(g, ε)", "type": "numeric", "correctValue": 48.9, "tolerance": 0.5, "unit": "°"}, {"id": "d", "label": "d) Normalabstand d(R, ε) des Punkts R(6|4|−2)", "type": "numeric", "correctValue": 3.73, "tolerance": 0.05}, {"id": "e", "label": "e) Koordinaten eines Punkts T mit Normalabstand d = 33 (ein Beispiel genügt)", "type": "free_text"}]'::jsonb)
on conflict (id) do nothing;

-- Teil B, Aufgabe 4: rational function — domain/zeros, asymptotes,
-- extrema, and (deliberately) no inflection points, since f'' is never 0.
insert into public.questions (id, test_id, position, category, type, text, parts)
values
  ('epm-abschluss-2-q4', 'epm-abschluss-2', 4, 'Часть Б', 'multi_part',
   'Gegeben ist die Funktion f(x) = (x² + x − 2) / (2x − 4). Die zweite Ableitung f''''(x) = 4 / (x − 2)³ dürfen Sie ohne Berechnung verwenden.',
   '[{"id": "a-gap", "label": "a) Definitionslücke (ausgeschlossener x-Wert)", "type": "numeric", "correctValue": 2, "tolerance": 0.01}, {"id": "a-null1", "label": "a) Nullstelle (kleinerer x-Wert)", "type": "numeric", "correctValue": -2, "tolerance": 0.01}, {"id": "a-null2", "label": "a) Nullstelle (größerer x-Wert)", "type": "numeric", "correctValue": 1, "tolerance": 0.01}, {"id": "b-vert", "label": "b) Senkrechte Asymptote — x-Wert", "type": "numeric", "correctValue": 2, "tolerance": 0.01}, {"id": "b-slope", "label": "b) Schräge Asymptote — Steigung m (y = mx + t)", "type": "numeric", "correctValue": 0.5, "tolerance": 0.01}, {"id": "b-intercept", "label": "b) Schräge Asymptote — y-Achsenabschnitt t", "type": "numeric", "correctValue": 1.5, "tolerance": 0.01}, {"id": "c-max-x", "label": "c) Maximum — x-Koordinate", "type": "numeric", "correctValue": 0, "tolerance": 0.01}, {"id": "c-max-y", "label": "c) Maximum — y-Koordinate", "type": "numeric", "correctValue": 0.5, "tolerance": 0.01}, {"id": "c-min-x", "label": "c) Minimum — x-Koordinate", "type": "numeric", "correctValue": 4, "tolerance": 0.01}, {"id": "c-min-y", "label": "c) Minimum — y-Koordinate", "type": "numeric", "correctValue": 4.5, "tolerance": 0.01}, {"id": "c-infl", "label": "c) Wendepunkte (mit Begründung)", "type": "free_text"}, {"id": "d", "label": "d) Skizzieren Sie den Graphen der Funktion f!", "type": "free_text"}]'::jsonb)
on conflict (id) do nothing;

-- Aufgabe 5 (Teil B): Tangente/Kurvenskizze + 7 Bedingungen für f — reine
