  ('epd-musterpruefung-1-t1-a1', 'epd-musterpruefung-1', 1, 'Чтение', 'cloze',
   'Lesen Sie die folgende Zusammenfassung zum Text „Internetsucht“ (siehe Text links) und ergänzen Sie die Lücken jeweils mit einem passenden Wort aus dem Originaltext.', 'text1', '{"template": "Hannelore K., eine 52-jährige Mutter von zwei Kindern, {1} im Internet das Plaudern in Chatrooms. Das machte ihr bald so viel Spaß (0 = Beispiel), dass sie oft 40 Stunden ohne Pause chattete. Als sie beinahe ihren Job verloren hätte, ging sie zum Arzt. Ihre Krankheit wird als krankhafter {2} bezeichnet. Derzeit sind weniger Österreicher von Opiaten {3} als vom Internet. Vor {4} Menschen, die alleine leben, arbeitslos sind und allgemein zu Suchtverhalten tendieren, sind davon betroffen.\n\nBei einer Befragung von Chatroom-Benutzern gab ein Drittel an, bei der virtuellen Kommunikation in {5} Zustände zu verfallen. Oft wird die Sucht erst {6}, wenn der Abhängige vom Arbeitsplatz fernbleibt, weil er {7} nicht schläft, oder wenn Beziehungen kaputt gehen, weil man sich keine Zeit mehr dafür nimmt.\n\nNicht nur das Chatten, sondern auch ein {8} kann bei manchen Menschen zur Sucht werden. Dann hilft nur mehr eine {9}. Laut Poppe könne jeder süchtig werden. Wer aber zu wenig {10} hat, ist eher dafür anfällig — wie bei jeder anderen Sucht auch.", "blanks": {"1": {"acceptedAnswers": ["entdeckte"]}, "2": {"acceptedAnswers": ["Internetgebrauch"]}, "3": {"acceptedAnswers": ["abhängig"]}, "4": {"acceptedAnswers": ["allem"]}, "5": {"acceptedAnswers": ["rauschähnliche", "rauschartige"]}, "6": {"acceptedAnswers": ["erkannt"]}, "7": {"acceptedAnswers": ["nächtelang"]}, "8": {"acceptedAnswers": ["Spiel", "Computergame"]}, "9": {"acceptedAnswers": ["Psychotherapie"]}, "10": {"acceptedAnswers": ["Selbstwertgefühl"]}}}'::jsonb)
on conflict (id) do nothing;

insert into public.questions (id, test_id, position, category, type, text, passage_id, qa_table)
