  ('epd-musterpruefung-1-t1-a2', 'epd-musterpruefung-1', 2, 'Чтение', 'qa_table',
   'Worauf beziehen sich die im Text unterstrichenen Wörter?', 'text1', '{"rows": [{"id": "ex", "prompt": "Bis __sie__ das Plaudern in Chatrooms im Internet entdeckte.", "given": "Hannelore K."}, {"id": "1", "prompt": "__Dabei__ entwickelte sie mehrere Identitäten und…", "acceptedAnswers": ["das Chatten", "beim Chatten", "Chatten"]}, {"id": "2", "prompt": "…, __das__ sind drei Prozent aller täglichen User.", "acceptedAnswers": ["30.000 Personen", "die 30.000 Personen", "30000 Personen"]}, {"id": "3", "prompt": "„__Sie__ fallen immer mehr am Arbeitsplatz aus, …“", "acceptedAnswers": ["die Betroffenen", "Betroffene", "Betroffenen"]}]}'::jsonb)
