  ('epd-musterpruefung-1-t3-a1', 'epd-musterpruefung-1', 5, 'Чтение', 'tf_table',
   'Text 3 (10 Punkte). Entscheiden Sie, ob folgende Aussagen richtig oder falsch sind und finden Sie den Satz, der diese Frage beantwortet. Tragen Sie die ersten vier Wörter dieses Satzes in die entsprechende Tabellenspalte ein. Nur, wenn dieser Satzhinweis stimmt, bekommen Sie einen Punkt für die korrekte Antwort.', 'text3', '{"rows": [{"id": "0", "statement": "Die Menschen haben heute immer weniger Bezug zu ihren Vierbeinern.", "correct": false, "words": ["Die", "Beziehung", "zum", "Haustier"], "isExample": true}, {"id": "1", "statement": "Äußere Merkmale erzeugen den Wunsch, sich um ein Tier zu kümmern.", "correct": true, "words": ["Attribute", "wie", "ein", "großer"]}, {"id": "2", "statement": "Jedes Tier kann das Streben des Menschen nach Beziehung befriedigen.", "correct": false, "words": ["Dass", "sich", "domestizierte", "Vierbeiner"]}, {"id": "3", "statement": "In Gruppen lebende Tiere haben wegen der Beziehungen innerhalb der Gruppe den meisten Stress.", "correct": true, "words": ["Neuere", "Forschungen", "zeigen", "dass"]}, {"id": "4", "statement": "Haustiere können die Betreuung älterer Menschen übernehmen.", "correct": false, "words": ["Sowohl", "in", "der", "Therapie"]}, {"id": "5", "statement": "Es wurde erhoben, dass Heimtiere insgesamt gesünder sind.", "correct": false, "words": ["Eine", "Studie", "bei", "knapp"]}]}'::jsonb)
on conflict (id) do nothing;

