  ('epd-musterpruefung-1-t4-a1', 'epd-musterpruefung-1', 6, 'Чтение', 'cloze',
   'Text 4 (5 Punkte). Lesen Sie den folgenden Text und entscheiden Sie, welches von den unten angeführten Wörtern in die jeweilige Lücke passt. Es gibt zu jeder Lücke vier Möglichkeiten (a-d). Ein Beispiel (0) ist vorgegeben.', 'text4', '{"template": "Nach neuesten Untersuchungen (0) von UNICEF wird in diesem Jahr die Zahl der Kinder, die nicht zur Schule gehen, voraussichtlich erstmal unter 100 Millionen {1}. Zu Beginn des Jahrtausends waren weltweit noch 121 Millionen Kinder im Grundschulalter {2} Schulbesuch ausgeschlossen. Dies geht aus dem heute veröffentlichten UNICEF-Bericht „Fortschritt für Kinder“ hervor, der den Schulbesuch von Mädchen und Jungen in 180 Ländern untersucht. Der Bericht überprüft die Umsetzung des Millenium-Ziels der Vereinten Nationen, bis 2015 alle Kinder in die Schule zu bringen. Das Fazit: Es gehen heute zwar mehr Kinder zur Schule als jemals zuvor.\n\nDoch die {3} beim Zugang zur Grundbildung in den ärmsten Ländern der Erde sind nicht schnell und nicht nachhaltig genug. Ohne massive zusätzliche Investitionen der betroffenen Länder und internationale Hilfe werden die {4} afrikanischen Staaten südlich der Sahara und Südasiens das Ziel „Bildung für Kinder“ bis 2015 nicht {5}.", "blanks": {"1": {"type": "choice", "options": [{"id": "a", "text": "sinken"}, {"id": "b", "text": "senken"}, {"id": "c", "text": "steigen"}, {"id": "d", "text": "steigern"}], "correctOptionId": "a"}, "2": {"type": "choice", "options": [{"id": "a", "text": "beim"}, {"id": "b", "text": "für"}, {"id": "c", "text": "im"}, {"id": "d", "text": "vom"}], "correctOptionId": "d"}, "3": {"type": "choice", "options": [{"id": "a", "text": "Ergebnisse"}, {"id": "b", "text": "Fortschritte"}, {"id": "c", "text": "Zahlen"}, {"id": "d", "text": "Ziele"}], "correctOptionId": "b"}, "4": {"type": "choice", "options": [{"id": "a", "text": "alle"}, {"id": "b", "text": "einigen"}, {"id": "c", "text": "meisten"}, {"id": "d", "text": "viele"}], "correctOptionId": "c"}, "5": {"type": "choice", "options": [{"id": "a", "text": "bekommen"}, {"id": "b", "text": "erfahren"}, {"id": "c", "text": "ergeben"}, {"id": "d", "text": "erreichen"}], "correctOptionId": "d"}}, "exampleChoice": {"label": "0", "options": [{"id": "a", "text": "Angeboten"}, {"id": "b", "text": "Bedürfnissen"}, {"id": "c", "text": "Unternehmen"}, {"id": "d", "text": "Untersuchungen"}], "correctOptionId": "d"}}'::jsonb)
on conflict (id) do nothing;

