  ('epd-musterpruefung-1-t5-a1', 'epd-musterpruefung-1', 7, 'Чтение', 'multi_part',
   'Text 5 (10 Punkte). Lesen Sie den folgenden Text und entscheiden Sie, welche der drei Aussagen (a, b oder c) richtig ist. Ein Beispiel (0) ist vorgegeben.', 'text5', '[{"id": "0", "label": "Das Buch „The Good Life“", "type": "single_choice", "options": [{"id": "a", "text": "erschien in den Vereinigten Staaten schon im Jahr 1938."}, {"id": "b", "text": "fasst die bisherigen Ergebnisse einer Studie zusammen."}, {"id": "c", "text": "wurde von der Universität Harvard herausgegeben."}], "correctOptionId": "b", "isExample": true}, {"id": "1", "label": "1. Was Menschen glücklich macht,", "type": "single_choice", "options": [{"id": "a", "text": "hat sich im Laufe der Geschichte radikal verändert."}, {"id": "b", "text": "kann sich während eines Lebens stark verändern."}, {"id": "c", "text": "sind Wohlstand, Bekanntheit und eine großartige Karriere."}], "correctOptionId": "b"}, {"id": "2", "label": "2. Die Harvard-Studie zum menschlichen Wohlbefinden", "type": "single_choice", "options": [{"id": "a", "text": "basiert auf der Befragung von 2000 über 80-jährigen Menschen."}, {"id": "b", "text": "ist ein einzigartiges Forschungsprojekt mit 2000 Befragten."}, {"id": "c", "text": "ist eine 80 Jahre alte Untersuchung von 2000 Patienten."}], "correctOptionId": "b"}, {"id": "3", "label": "3. Die Studie beschäftigt sich primär", "type": "single_choice", "options": [{"id": "a", "text": "mit der Frage, was die Testpersonen glücklich macht."}, {"id": "b", "text": "mit einem äußerst komplexen Studiendesign."}, {"id": "c", "text": "mit verschiedenen Faktoren, die unser Leben positiv oder negativ beeinflussen."}], "correctOptionId": "a"}, {"id": "4", "label": "4. Die Durchführung der Studie war schwierig,", "type": "single_choice", "options": [{"id": "a", "text": "weil das menschliche Glücksempfinden von multiplen Faktoren abhängig ist."}, {"id": "b", "text": "weil die sozioökonomische Situation der Teilnehmenden herausfordernd war."}, {"id": "c", "text": "weil junge Menschen noch keine klar definierten Lebensziele haben."}], "correctOptionId": "a"}, {"id": "5", "label": "5. Das wichtigste Ergebnis der Studie ist,", "type": "single_choice", "options": [{"id": "a", "text": "dass die Beziehungen zu anderen das bedeutendste Glücks-Kriterium sind."}, {"id": "b", "text": "dass die Dinge, die uns glücklich machen, individuell sehr verschieden sind."}, {"id": "c", "text": "dass Menschen in Paarbeziehungen glücklicher sind als Singles."}], "correctOptionId": "a"}, {"id": "6", "label": "6. Die Studie zeigt außerdem, dass Erfolg, Wohlstand und Gesundheitsbewusstsein", "type": "single_choice", "options": [{"id": "a", "text": "für das Glücksempfinden von zentraler Bedeutung sind."}, {"id": "b", "text": "nur einen Teil des Wohlbefindens ausmachen."}, {"id": "c", "text": "nur im fortgeschrittenen Alter von Bedeutung sind."}], "correctOptionId": "b"}, {"id": "7", "label": "7. Eine falsche Vorstellung vom Glück", "type": "single_choice", "options": [{"id": "a", "text": "besteht im Irrglauben, dass man dieses kaufen kann."}, {"id": "b", "text": "besteht darin, dass man dieses für unerreichbar hält."}, {"id": "c", "text": "wird von den Medien in die Welt gesetzt."}], "correctOptionId": "c"}, {"id": "8", "label": "8. R. Waldinger ist der Ansicht, dass", "type": "single_choice", "options": [{"id": "a", "text": "der Aufbau von Muskeln die psychische Gesundheit fördert."}, {"id": "b", "text": "Fremde, Nachbarn und nahestehende Personen einander unterstützen können."}, {"id": "c", "text": "Menschen ihre Sozialkompetenz weiterentwickeln können und sollten."}], "correctOptionId": "c"}, {"id": "9", "label": "9. Menschen leben länger und gesünder,", "type": "single_choice", "options": [{"id": "a", "text": "wenn sie andere wertschätzen und nicht ausbeuten."}, {"id": "b", "text": "wenn sie auf ihre Blutwerte und Stresshormone achten."}, {"id": "c", "text": "wenn sie gute Beziehungen zu ihren Mitmenschen pflegen."}], "correctOptionId": "c"}, {"id": "10", "label": "10. Ein Zusammenhang zwischen psychischer und körperlicher Gesundheit", "type": "single_choice", "options": [{"id": "a", "text": "kann bei unfreiwillig einsamen Menschen verstärkt beobachtet werden."}, {"id": "b", "text": "konnte durch die Harvard-Studie nicht eindeutig belegt werden."}, {"id": "c", "text": "zeigt sich häufig bei Menschen, die schon lange verheiratet sind."}], "correctOptionId": "a"}]'::jsonb)
on conflict (id) do nothing;

