": "D", "text": "wenn das Telefon in der Tasche bleiben würde"}, {"id": "E", "text": "dass man einen Freund dadurch verliert"}, {"id": "F", "text": "dass hier ein Mechanismus des technischen Fortschritts am Werk ist"}, {"id": "G", "text": "führte das Versuchssetting zu messbaren Effekten"}, {"id": "H", "text": "ihrem Gesprächspartner nicht so nahe gewesen zu sein"}, {"id": "I", "text": "laufen die Gespräche schlechter"}, {"id": "J", "text": "lenke damit tendenziell von der Intimität des Vieraugengesprächs ab"}, {"id": "K", "text": "sich zu einem Gespräch in einem Lokal zu treffen"}, {"id": "L", "text": "während die Handyfraktion die Konversation als eher oberflächlich erlebte"}], "correctOptionId": "C"}, "10": {"type": "choice", "options": [{"id": "A", "text": "aber sie können diese Verbindung durch ihre Präsenz auch hemmen"}, {"id": "B", "text": "als ob man einen wichtigen Anruf erwarten würde"}, {"id": "C", "text": "bleibt noch zu klären"}, {"id": "D", "text": "wenn das Telefon in der Tasche bleiben würde"}, {"id": "E", "text": "dass man einen Freund dadurch verliert"}, {"id": "F", "text": "dass hier ein Mechanismus des technischen Fortschritts am Werk ist"}, {"id": "G", "text": "führte das Versuchssetting zu messbaren Effekten"}, {"id": "H", "text": "ihrem Gesprächspartner nicht so nahe gewesen zu sein"}, {"id": "I", "text": "laufen die Gespräche schlechter"}, {"id": "J", "text": "lenke damit tendenziell von der Intimität des Vieraugengesprächs ab"}, {"id": "K", "text": "sich zu einem Gespräch in einem Lokal zu treffen"}, {"id": "L", "text": "während die Handyfraktion die Konversation als eher oberflächlich erlebte"}], "correctOptionId": "A"}}}'::jsonb)
