-- Textproduktion (Teil D) — essay_choice: pick one of two Schreibaufgaben,
-- write a free-form text. Never auto-graded — TestPage.jsx persists the
-- written answer to essay_submissions once it locks, viewable later under
-- МОЁ ОБУЧЕНИЕ → «Мои сочинения».
insert into public.questions (id, test_id, position, category, type, text, essay_choice)
values
  ('epd-musterpruefung-1-schreiben', 'epd-musterpruefung-1', 12, 'Письмо', 'essay_choice',
   'Textproduktion (Teil D). Wählen Sie EINE der beiden folgenden Schreibaufgaben aus und verfassen Sie einen eigenständigen Text dazu. Auswendig Gelerntes wird nicht akzeptiert.', '{"options": [{"id": "a", "title": "Schreibaufgabe 1", "text": "Neue Ernährungstrends\n\nAuch wenn Fleisch noch immer ein ganz zentrales Nahrungsmittel für viele Österreicher und Österreicherinnen ist, ist deutlich zu beobachten, dass Getreide und Gemüse in der Ernährung einen neuen Stellenwert gewinnen. Fleisch hat deutlich an Attraktivität verloren. Die ethischen und ökologischen Debatten haben – vor allem bei jüngeren Konsumenten und Konsumentinnen – ihre Spuren auch im Geschmack hinterlassen. Es kommt eine Generation nach, für die Fleisch nichts Besonderes mehr ist und die neugierig auf Alternativen ist. Insbesondere pflanzliche Proteine, wie Hülsenfrüchte, Tofu und neue Fleischersatzprodukte, erfreuen sich wachsender Beliebtheit. Zudem rücken auch „Superfoods“ wie Quinoa und Chiasamen stärker in den Fokus, die eine gesunde und nachhaltige Ernährung unterstützen.", "image": "", "instructions": ["Geben Sie einleitend kurz die zentrale Aussage des Textausschnitts in eigenen Worten wieder.", "Nehmen Sie zu ausgewählten Aspekten des Textausschnitts Stellung. Begründen Sie Ihre Meinung mit sachlichen Argumenten.", "Schlagen Sie eine Ernährungsweise vor, die sowohl ökologische als auch gesundheitliche Aspekte berücksichtigt. Begründen Sie Ihre Vorschläge."]}, {"id": "b", "title": "Schreibaufgabe 2", "text": "", "image": "epd-musterpruefung-1-schreiben2", "instructions": ["Beschreiben Sie einleitend kurz in eigenen Worten, worum es in der Grafik geht. (Achtung: Eine detaillierte Beschreibung der Grafik ist nicht gefragt!)", "Nehmen Sie zu ausgewählten Informationen der Grafik Stellung. Begründen Sie Ihre Meinung mit sachlichen Argumenten.", "Schlagen Sie Maßnahmen vor, die das Wohnen in Wien für junge Menschen attraktiver machen könnten. Begründen Sie Ihre Vorschläge."]}]}'::jsonb)
on conflict (id) do nothing;

-- C. Strukturen und Wortschatz (Teil C) — always these same two task
-- shapes across Musterprüfungen (only the topic/sentences change):
-- Aufgabe 1 = rewrite an underlined nominal structure as a verbal one
-- (whole sentence), Aufgabe 2 = continue given sentence openers
-- logically. Both are open-ended writing with no single correct answer
-- (freeText rows, never graded, matching the free_text precedent) —
-- built as qa_table (prompt | free-answer, table layout) rather than a
-- stacked multi_part, per the person's request to match the source
-- layout. The "Beispiel" box is shown as a photo (question.image)
-- instead of a table row, since it's a separate callout in the source,
-- not part of the table for Aufgabe 2, and easier to keep visually
-- faithful (bold/underline) as an image than to re-type with markup.
insert into public.questions (id, test_id, position, category, type, text, image, qa_table)
values
  ('epd-musterpruefung-1-struktur-a1', 'epd-musterpruefung-1', 13, 'Грамматика', 'qa_table',
   '1. Formen Sie bitte die unterstrichenen Nominalstrukturen zum Thema Arbeitswelt in Verbalstrukturen um, ohne den Inhalt zu verändern. Schreiben Sie dabei jeweils den ganzen (umgeformten) Satz. (Beispiel siehe Bild.)', 'epd-musterpruefung-1-struktur-a1-beispiel', '{"rows": [{"id": "1", "prompt": "1. __Laut den überzeugenden Ausführungen des renommierten Psychiaters Manfred Spitzer__ gefährden soziale Medien die psychische Gesundheit von Jugendlichen massiv.", "freeText": true, "after": ", gefährden soziale Medien die psychische Gesundheit von Jugendlichen massiv.", "points": 2}, {"id": "2", "prompt": "2. __Aufgrund des skrupellosen Einsatzes von manipulierenden Algorithmen durch die großen Digitalkonzerne__ entwickeln immer mehr Jugendliche ein suchtähnliches Nutzungsverhalten.", "freeText": true, "after": "entwickeln immer mehr Jugendliche ein suchtähnliches Nutzungsverhalten.", "points": 2}, {"id": "3", "prompt": "3. Expert:innen sehen neben einem Social-Media-Verbot für Jugendliche in klaren rechtlichen Rahmenbedingungen den Schlüssel __zur Eindämmung von exzessiver Nutzung und anderen Gefahren im Netz__.", "freeText": true, "after": "", "points": 2}]}'::jsonb)
on conflict (id) do nothing;

insert into public.questions (id, test_id, position, category, type, text, image, qa_table)
values
  ('epd-musterpruefung-1-struktur-a2', 'epd-musterpruefung-1', 14, 'Грамматика', 'qa_table',
   '2. Bitte setzen Sie die Satzanfänge zum Thema Sucht inhaltlich und sprachlich korrekt und logisch fort. Verwenden Sie dabei verschiedene Verben und komplexe Strukturen sowie einen inhaltsadäquaten und differenzierten Wortschatz. Variieren Sie die Satzanschlüsse. Sie erhalten für einfache Sätze 2 Punkte, für komplexere Sätze 3 Punkte. (Beispiel siehe Bild.)', 'epd-musterpruefung-1-struktur-a2-beispiel', '{"rows": [{"id": "1", "prompt": "1. Eine Folge der Drogensucht besteht darin,", "freeText": true}, {"id": "2", "prompt": "2. Alkohol und Nikotin zählen zwar auch zu den Drogen,", "freeText": true}, {"id": "3", "prompt": "3. Je selbstbewusster Jugendliche sind,", "freeText": true}]}'::jsonb)
on conflict (id) do nothing;

-- ---- EPD oral: model exam (not a probnik) — shows the exam format and
-- all 4 possible monologue-task types at once (Grafik, Kurztext,
-- Karikatur, Zitat), instead of the real exam's 2. examInfo is the
-- translated standard oral-exam intro (shown once per exam, dismissible
-- — see OralTestPage.jsx's showIntro/localStorage logic).
insert into public.tests
  (id, exam_key, title, short_description, full_description, is_official, is_model, topic, format, year, duration_minutes, oral_task)
values
  ('epd-oral-model-1', 'epd', 'Модель устного экзамена',
   'Модель устной части EPD — знакомит с форматом экзамена и всеми возможными типами заданий монологической части.',
   'Это не пробник, а модель экзамена: показывает формат устной части EPD и все 4 возможных типа задания для монологической части (на самом экзамене предлагаются только 2 на выбор).',
   true, true, 'environment', 'oral', 2026, 40,
   '{"stages": [{"id": "monolog", "title": "Monologischer Teil", "kind": "choice", "instructions": "Wählen Sie eines der folgenden 4 Beispiele für die monologische Aufgabe und bereiten Sie eine Kurzpräsentation (ca. 5 Minuten) anhand der Leitfragen vor.", "prepMinutes": 15, "options": [{"id": "1a", "label": "1a. Grafik", "kind": "image", "image": "epd-oral-model-1-grafik", "leitfragen": ["Fassen Sie die wichtigsten Informationen der Grafik zusammen.", "Erzählen Sie, welche Wohnformen in Ihrem Heimatland üblich für Student/innen sind.", "Welche Vor- und Nachteile bietet ein Studentenwohnheim?", "Wie möchten Sie in 10 Jahren gerne leben?", "Welche Maßnahmen könnten gesetzt werden, um Studierenden die Suche nach Wohnplätzen zu erleichtern?"]}, {"id": "1b", "label": "1b. Kurztext", "kind": "text", "content": "Nachhaltiger Lebensstil\n\nMit Sicherheit hat mittlerweile jede/r mitbekommen, dass ein nachhaltiger Lifestyle für viele Menschen immer wichtiger wird. Nachhaltigkeit ist inzwischen fast schon zu einer Art Lebenskonzept geworden. Denn sie lässt sich in verschiedenen Bereichen des Alltags recht einfach umsetzen. Nachhaltigkeit lässt sich etwa rund um die Art der genutzten Energie bis hin zur Wahl der Kleidung leben. Ein nachhaltiger Lebensstil trägt in erster Linie dazu bei, die Umwelt zu schützen und die unnötige Verschwendung von Ressourcen zu verringern. Der Duden definiert Nachhaltigkeit als „Prinzip, nach dem nicht mehr verbraucht werden darf, als jeweils nachwachsen, sich regenerieren, künftig wieder bereitgestellt werden kann“.", "leitfragen": ["Fassen Sie den Inhalt des Kurztextes zusammen. Worum geht es? Erklären Sie.", "Äußern Sie Ihre Meinung zu der Aussage.", "Nennen Sie Möglichkeiten, als Privatperson nachhaltig zu leben.", "Analysieren Sie, ob Nachhaltigkeit in Ihrer Generation wichtig ist oder nicht.", "Machen Sie Vorschläge, wie man junge Menschen dazu animieren könnte, umweltbewusst einzukaufen."]}, {"id": "1c", "label": "1c. Karikatur", "kind": "image", "image": "epd-oral-model-1-karikatur", "leitfragen": ["Beschreiben Sie die beiden Cartoons und gehen Sie dabei auf die dargestellten Personen und Situationen ein.", "Erklären und deuten Sie die Aussagen der Karikaturen und heben Sie hervor, welche Kritik an der Studien- und Berufswahl formuliert wird.", "Vergleichen Sie die beiden Darstellungen miteinander und übertragen Sie sie auf reale Erfahrungen.", "Analysieren Sie die gesellschaftlichen Hintergründe, die hier sichtbar werden, und gehen Sie auf die Rolle von Schule, Hochschule und/oder Arbeitsmarkt ein.", "Nehmen Sie begründet Stellung zu folgender Aussage: „Die heutige Studien- und Berufswahl bietet zu viel Auswahl, aber zu wenig echte Orientierung.“"]}, {"id": "1d", "label": "1d. Zitat", "kind": "text", "content": "„Wer sein Land nie verlassen hat, ist voller Vorurteile.“\n— Carlo Goldoni\n\n„Der Tourismus soll zur internationalen Verständigung, zum Frieden, zum Wohlstand und zur allgemeinen Wahrung der Menschenrechte beitragen.“\n— Aus dem Statut der Welttourismusorganisation", "leitfragen": ["Geben Sie die Zitate in eigenen Worten wieder.", "Verdeutlichen Sie die Hauptaussagen der beiden Zitate.", "Schätzen Sie ab, inwiefern der Tourismus zum Abbau von Vorurteilen beitragen kann.", "Weisen Sie nach, inwiefern der Tourismus zur internationalen Verständigung und zur Wahrung der Menschenrechte beitragen kann.", "Sie sollen nun versuchen, diesen beiden Zitaten/Aussagen zu widersprechen. Wählen Sie Situationen aus, die Ihre Argumente stützen."]}]}, {"id": "dialog", "title": "Dialogischer Teil", "kind": "choice", "instructions": "Den Impuls für den dialogischen Teil erhalten Sie erst im Anschluss an Ihre Präsentation. Wählen Sie eines der folgenden 4 Beispiele und führen Sie darüber ein etwa fünfminütiges, spontanes Gespräch — ohne Vorbereitungszeit.", "prepMinutes": 0, "options": [{"id": "2a", "label": "2a. Bildimpuls", "kind": "image", "image": "epd-oral-model-1-bildimpuls", "leitfragen": ["Beschreiben Sie das Bild und interpretieren Sie die Situation. Um welches Thema könnte es sich hier handeln?", "Erklären Sie, welche Gründe Menschen haben können, beim Sport ihr Leben zu riskieren.", "Nennen Sie mögliche Nachteile von Extremsportarten.", "Diskutieren Sie: Sollten Extremsportler, die ihre Gesundheit aufs Spiel setzen, höhere Krankenversicherungsbeiträge bezahlen? Warum? Warum nicht?"]}, {"id": "2b", "label": "2b. Einfache Grafik", "kind": "image", "image": "epd-oral-model-1-2b-grafik", "leitfragen": ["Fassen Sie die Kernaussage der Grafik zusammen. Was ist das Thema?", "Beschreiben Sie, wie sich Vegetarier und Veganer ernähren.", "Erklären Sie, warum der Konsum von Fleisch schlecht für das Klima ist.", "Welche anderen Gründe als den Klimaschutz kann man haben, sich vegetarisch oder vegan zu ernähren?", "Können Sie sich selbst vorstellen, sich vegetarisch oder vegan zu ernähren? Warum? Warum nicht?", "Worauf achten Sie bei Ihrer Ernährung besonders?"]}, {"id": "2c", "label": "2c. Zitat", "kind": "quote", "content": "Eine Fremdsprache lernt man, um in einem fremden Land nicht nur ein Fremder zu sein.", "leitfragen": ["Lesen Sie das Zitat laut vor und erklären Sie in eigenen Worten, was es bedeutet. Versuchen Sie es zu interpretieren. Um welches Thema geht es hier?", "Warum ist es wichtig, die Sprache des Landes, in dem man lebt, gut zu beherrschen? Welche anderen Aspekte finden Sie wichtig, wenn man in einem fremden Land lebt?", "Welche Erfahrung haben Sie selbst beim Deutschlernen gemacht?", "Was ist für Sie die beste Methode, um eine Fremdsprache zu lernen?", "Welche Fremdsprachen würden Sie in Zukunft gerne noch lernen? Warum?"]}, {"id": "2d", "label": "2d. Aussage", "kind": "text", "content": "Wie lautet Ihre Meinung? (Wählen Sie eine Aussage für die Diskussion.)\n\n1. Der Tourismus ist in vielen Ländern für die Umweltzerstörung verantwortlich.\n\n2. Heutzutage ist es problemlos möglich zu reisen und dabei die Umwelt zu schonen.", "leitfragen": ["Welche Formen des Tourismus belasten die Umwelt besonders stark?", "Wie wirkt sich Tourismus auf die lokale Bevölkerung aus?", "Welche Verantwortung tragen Reisende?", "Welche Konzepte für nachhaltigen Tourismus sind Ihnen bekannt?", "Wie könnte man Umweltzerstörung durch Tourismus reduzieren?", "Welche langfristigen Folgen kann intensiver Tourismus haben?"]}]}]}'::jsonb)
on conflict (id) do nothing;

-- Existing rows from before stage 2 (dialogischer Teil) was added
-- won't pick it up via ON CONFLICT DO NOTHING — this makes sure it's
-- set either way, matching the pattern already used for `passages`.
update public.tests set oral_task = '{"stages": [{"id": "monolog", "title": "Monologischer Teil", "kind": "choice", "instructions": "Wählen Sie eines der folgenden 4 Beispiele für die monologische Aufgabe und bereiten Sie eine Kurzpräsentation (ca. 5 Minuten) anhand der Leitfragen vor.", "prepMinutes": 15, "options": [{"id": "1a", "label": "1a. Grafik", "kind": "image", "image": "epd-oral-model-1-grafik", "leitfragen": ["Fassen Sie die wichtigsten Informationen der Grafik zusammen.", "Erzählen Sie, welche Wohnformen in Ihrem Heimatland üblich für Student/innen sind.", "Welche Vor- und Nachteile bietet ein Studentenwohnheim?", "Wie möchten Sie in 10 Jahren gerne leben?", "Welche Maßnahmen könnten gesetzt werden, um Studierenden die Suche nach Wohnplätzen zu erleichtern?"]}, {"id": "1b", "label": "1b. Kurztext", "kind": "text", "content": "Nachhaltiger Lebensstil\n\nMit Sicherheit hat mittlerweile jede/r mitbekommen, dass ein nachhaltiger Lifestyle für viele Menschen immer wichtiger wird. Nachhaltigkeit ist inzwischen fast schon zu einer Art Lebenskonzept geworden. Denn sie lässt sich in verschiedenen Bereichen des Alltags recht einfach umsetzen. Nachhaltigkeit lässt sich etwa rund um die Art der genutzten Energie bis hin zur Wahl der Kleidung leben. Ein nachhaltiger Lebensstil trägt in erster Linie dazu bei, die Umwelt zu schützen und die unnötige Verschwendung von Ressourcen zu verringern. Der Duden definiert Nachhaltigkeit als „Prinzip, nach dem nicht mehr verbraucht werden darf, als jeweils nachwachsen, sich regenerieren, künftig wieder bereitgestellt werden kann“.", "leitfragen": ["Fassen Sie den Inhalt des Kurztextes zusammen. Worum geht es? Erklären Sie.", "Äußern Sie Ihre Meinung zu der Aussage.", "Nennen Sie Möglichkeiten, als Privatperson nachhaltig zu leben.", "Analysieren Sie, ob Nachhaltigkeit in Ihrer Generation wichtig ist oder nicht.", "Machen Sie Vorschläge, wie man junge Menschen dazu animieren könnte, umweltbewusst einzukaufen."]}, {"id": "1c", "label": "1c. Karikatur", "kind": "image", "image": "epd-oral-model-1-karikatur", "leitfragen": ["Beschreiben Sie die beiden Cartoons und gehen Sie dabei auf die dargestellten Personen und Situationen ein.", "Erklären und deuten Sie die Aussagen der Karikaturen und heben Sie hervor, welche Kritik an der Studien- und Berufswahl formuliert wird.", "Vergleichen Sie die beiden Darstellungen miteinander und übertragen Sie sie auf reale Erfahrungen.", "Analysieren Sie die gesellschaftlichen Hintergründe, die hier sichtbar werden, und gehen Sie auf die Rolle von Schule, Hochschule und/oder Arbeitsmarkt ein.", "Nehmen Sie begründet Stellung zu folgender Aussage: „Die heutige Studien- und Berufswahl bietet zu viel Auswahl, aber zu wenig echte Orientierung.“"]}, {"id": "1d", "label": "1d. Zitat", "kind": "text", "content": "„Wer sein Land nie verlassen hat, ist voller Vorurteile.“\n— Carlo Goldoni\n\n„Der Tourismus soll zur internationalen Verständigung, zum Frieden, zum Wohlstand und zur allgemeinen Wahrung der Menschenrechte beitragen.“\n— Aus dem Statut der Welttourismusorganisation", "leitfragen": ["Geben Sie die Zitate in eigenen Worten wieder.", "Verdeutlichen Sie die Hauptaussagen der beiden Zitate.", "Schätzen Sie ab, inwiefern der Tourismus zum Abbau von Vorurteilen beitragen kann.", "Weisen Sie nach, inwiefern der Tourismus zur internationalen Verständigung und zur Wahrung der Menschenrechte beitragen kann.", "Sie sollen nun versuchen, diesen beiden Zitaten/Aussagen zu widersprechen. Wählen Sie Situationen aus, die Ihre Argumente stützen."]}]}, {"id": "dialog", "title": "Dialogischer Teil", "kind": "choice", "instructions": "Den Impuls für den dialogischen Teil erhalten Sie erst im Anschluss an Ihre Präsentation. Wählen Sie eines der folgenden 4 Beispiele und führen Sie darüber ein etwa fünfminütiges, spontanes Gespräch — ohne Vorbereitungszeit.", "prepMinutes": 0, "options": [{"id": "2a", "label": "2a. Bildimpuls", "kind": "image", "image": "epd-oral-model-1-bildimpuls", "leitfragen": ["Beschreiben Sie das Bild und interpretieren Sie die Situation. Um welches Thema könnte es sich hier handeln?", "Erklären Sie, welche Gründe Menschen haben können, beim Sport ihr Leben zu riskieren.", "Nennen Sie mögliche Nachteile von Extremsportarten.", "Diskutieren Sie: Sollten Extremsportler, die ihre Gesundheit aufs Spiel setzen, höhere Krankenversicherungsbeiträge bezahlen? Warum? Warum nicht?"]}, {"id": "2b", "label": "2b. Einfache Grafik", "kind": "image", "image": "epd-oral-model-1-2b-grafik", "leitfragen": ["Fassen Sie die Kernaussage der Grafik zusammen. Was ist das Thema?", "Beschreiben Sie, wie sich Vegetarier und Veganer ernähren.", "Erklären Sie, warum der Konsum von Fleisch schlecht für das Klima ist.", "Welche anderen Gründe als den Klimaschutz kann man haben, sich vegetarisch oder vegan zu ernähren?", "Können Sie sich selbst vorstellen, sich vegetarisch oder vegan zu ernähren? Warum? Warum nicht?", "Worauf achten Sie bei Ihrer Ernährung besonders?"]}, {"id": "2c", "label": "2c. Zitat", "kind": "quote", "content": "Eine Fremdsprache lernt man, um in einem fremden Land nicht nur ein Fremder zu sein.", "leitfragen": ["Lesen Sie das Zitat laut vor und erklären Sie in eigenen Worten, was es bedeutet. Versuchen Sie es zu interpretieren. Um welches Thema geht es hier?", "Warum ist es wichtig, die Sprache des Landes, in dem man lebt, gut zu beherrschen? Welche anderen Aspekte finden Sie wichtig, wenn man in einem fremden Land lebt?", "Welche Erfahrung haben Sie selbst beim Deutschlernen gemacht?", "Was ist für Sie die beste Methode, um eine Fremdsprache zu lernen?", "Welche Fremdsprachen würden Sie in Zukunft gerne noch lernen? Warum?"]}, {"id": "2d", "label": "2d. Aussage", "kind": "text", "content": "Wie lautet Ihre Meinung? (Wählen Sie eine Aussage für die Diskussion.)\n\n1. Der Tourismus ist in vielen Ländern für die Umweltzerstörung verantwortlich.\n\n2. Heutzutage ist es problemlos möglich zu reisen und dabei die Umwelt zu schonen.", "leitfragen": ["Welche Formen des Tourismus belasten die Umwelt besonders stark?", "Wie wirkt sich Tourismus auf die lokale Bevölkerung aus?", "Welche Verantwortung tragen Reisende?", "Welche Konzepte für nachhaltigen Tourismus sind Ihnen bekannt?", "Wie könnte man Umweltzerstörung durch Tourismus reduzieren?", "Welche langfristigen Folgen kann intensiver Tourismus haben?"]}]}]}'::jsonb where id = 'epd-oral-model-1';

-- =====================================================================
-- EPE Sample Written Exam (Sept 2024) — official VWU/aufgabenpool.at
-- sample tasks, one of each task type used across Reading Comprehension,
-- Language in Use and Text Production. Answers cross-checked against the
-- official key PDF where the key gave unambiguous single letters/words.
-- NOTE: the True/False (Task 1) and Multiple Matching 1 (Task 2) answer
-- keys came from a PDF table whose T/F and Sayeed/Maika/Mai-Hua-Ta
-- columns collapsed into a single "x" during text extraction, with no
-- way to tell which column the x was under — so those two tasks'
-- correct answers are my own content-based reading of the passages,
-- not a directly transcribed key. Everything else (Multiple Matching 2,
-- Multiple Choice, and all 6 Language in Use tasks) came from an
-- unambiguous key. Double check the two flagged ones if possible.
-- =====================================================================
insert into public.tests
  (id, exam_key, title, short_description, full_description, is_official, topic, format, year, duration_minutes, passages)
values
  ('epe-sample-1', 'epe', 'EPE Sample Written Exam (Sept 2024)',
   'Официальный образец письменного экзамена EPE — по одному заданию каждого типа из трёх частей: Reading Comprehension, Language in Use, Text Production.',
   'Официальный образец письменного экзамена EPE от VWU / aufgabenpool.at (по состоянию на сентябрь 2024). Содержит по одному образцу каждого типа задания из всех трёх частей письменного экзамена.',
   true, 'economy', 'written', 2024, 150,
   '[{"id": "cjsd", "category": "Чтение", "title": "Jobs: Creative Job Speed Dating", "text": "JOBS: CREATIVE JOB SPEED DATING\n\n\"OK ladies and gentlemen, let''s begin, you have 5 minutes starting now.\"\n\nWe were seated at a long black table in a 16th-floor suite at Sofitel Vienna Stephansdom. The five pairs engaged in conversation, asking questions, writing notes on carbon paper.\n\nI \"dated\" a food editor for Woman Magazine, an editor at a corporate publishing start-up, Managing Editor of the business magazine Format, a consultant at a corporate branding company and a recently unemployed advertising salesman, all in 25 minutes.\n\nCreative Job Speed Dating (CJSD) is the brainchild of interior and set designer Rikki Wieland, and fashion and advertising photographer Michael Dürr. They had invited mostly members of the press and PR community to this third session.\n\nThe idea grew out of Dürr''s birthday party in early 2013, where he had set up a room for traditional speed dating. While guests did seem to enjoy themselves and it served as a fast track for his friends and colleagues to get to know each other, those who were spoken for felt wary about joining in.\n\nBut they had plenty of reasons to talk, and so the idea for quickie \"dating\" for creative professionals was born.\n\nThe classic idea behind speed dating is a series of brief encounters: encapsulated life stories, informing, and perchance enticing the conversation partner in all of 5 minutes.\n\nAs freelancers, most people in the creative industry rely greatly on networking, but not everyone has the time or energy to go to event after event, hoping to strike up a helpful conversation. CJSD aims to make this easier. Some were sceptical about the idea at the Sofitel event in June, but then again, how bad could it be?\n\nThe worst that can happen is that you spend a few minutes talking to someone you''ll never work with. And the best case scenario can be a new job or project, or simply inspiration. So far, the \"speed dating\" events have drawn between 20 and 80 people.\n\nSome call it \"working the room\" – roaming around, introducing yourself and striking up conversations. While perhaps pushy, this is a necessary evil as a creative freelancer. In the CJSD setting, it is not crass to brag about ideas or projects you are proud of.\n\nEven asking professionally \"personal\" questions like \"how much does that cost?\" or \"how much does your company rely on ad revenue?\" is normal, even expected.\n\nIn the \"waiting room\", invitees said they actually got pitches for projects and ways to cooperate, simply because that''s what they were there for.\n\nIn September and October the team will be inviting fashion professionals to a Vienna-fashion-week-themed event, and in October it''s all about art, as Vienna is taken over by the VIENNAFAIR. So if you''re a designer, makeup artist, or fashion photographer – keep checking CJSD''s Facebook page for future dates and venues."}, {"id": "immigrants", "category": "Чтение", "title": "Three young immigrants", "text": "SAYEED\n\nMy father left Palestine when the war started and fled to Kuwait. He met my mother there, although she''s English, and I was born there. They sent me to school in England when I was 10, which I quite enjoyed. It was vastly different from life in Kuwait; there were so many rules and it seemed so alien to me. But I tried hard to fit in. We spoke English at home, so the language wasn''t a problem when I came to England. Nowadays I wish I had learnt Arabic while I was little, and not been so against learning it. I had a private tutor, but I''m afraid I was a horrible pupil. One day I really upset him so he wouldn''t come back and teach me any more!\n\nIt would have been nice to speak two languages fluently, but I think I''m not really talented as far as languages go. I''m hopeless at French, in spite of learning it for years at school.\n\nWhat I miss about life in Kuwait is the big family gatherings. There''s much more to family life than in England. But I like the freedom you have here too. Too much family can get annoying.\n\nI love Arabic food and I suppose I just copied my dad when it came to eating Arabic style. My brother and sister and I were not like typical Kuwaiti kids and he would always joke about us being \"weak from the English side\", although I know he was very proud of us too.\n\nIf I have a family I would want my children to belong to both cultures. I think it''s important not to deny your origins, and to continue being Palestinian. I think of myself as a \"double-caste\" not a \"half-caste\"!\n\nDuring the Gulf War I felt threatened, a bit less confident. But apart from some bad experiences when some people reacted badly to me, I''ve never been discriminated against. The only racist experiences I''ve had were in my head. In fact London especially is a very tolerant place. I like the way the English are straight with you, they don''t like airs and graces. They can be a bit conservative for my liking, and I can''t stand being patronised by some of them. But the variety of cultures is great, it makes London a great place to live in.\n\nMAIKA\n\nI came from Poland in 1989. It was quite unstable there then and life here in England seemed much easier. I was married to an Englishman and he was brought back here by his company. There are lots of differences, for example there''s a bigger variety of food here, with the Indian and Chinese restaurants, and so on. I had learnt English in school, but when I got here it wasn''t the same. Some accents, like cockney, are so difficult to understand!\n\nApart from my family and friends I don''t really feel I''m missing very much. It''s important to keep in touch and I do mix with Poles when I can. If I have children I want them to learn Polish and keep up the cultural traditions. Families in Poland are much closer than in Britain. I was amazed how some people here don''t see their sisters or brothers ever! In Poland it is more like it used to be here. They take care of the old people and there''s more discipline. Families help each other more.\n\nPeople here in England dress more casually, different than in Poland. They don''t care what they look like. But I enjoy the differences. The British are very tolerant and friendly. I''ll always be Polish, I think it''s impossible to change deep down, and I don''t see any advantage in changing.\n\nMAI HUA TA\n\nMy grandmother was one of the \"Boat People\" who left Vietnam in little boats to get away from persecution. We immigrated to Britain later when I was only seven. My grandmother came to the airport to meet us with loads of jackets, it was so cold. I''ll always remember seeing English people for the first time. Their hair is so colourful! And compared to us they are so big.\n\nIt was easy for me and my brother to learn English but my parents still don''t speak good English. They can get by in everyday situations but can''t really converse properly.\n\nMy mum still can''t use a knife and fork properly, but we children soon got used to everything. I''d never seen cheese before, and apples and grapes were very strange too.\n\nWe are ethnically Chinese, not Vietnamese, and in our tradition the old people are treated with a lot of respect. I want my children to learn that too, because after all, I''m going to be old one day too.\n\nI don''t want to go back to Vietnam. There''s a lot of corruption there and I''ve heard of people having to pay the police to stop them making trouble for them. My mum misses being with Chinese people but I find it better here. The standard of living is much higher, though I miss the family closeness, and some of the food.\n\nThe older generation Chinese people are very strict with the young people. You are not supposed to kiss your boyfriend, or even hold hands in public. There''s too much gossip. I don''t mix with the Chinese much. There''s more freedom here. I like the British, I like their openness, and they are more straightforward than the Chinese. But I want my children to learn Chinese, I want the best of both cultures."}, {"id": "vegas", "category": "Чтение", "title": "History of Las Vegas", "text": "HISTORY OF LAS VEGAS\n\nThe first Las Vegas Strip hotel, the El Rancho, opened in 1941. It became famous for its \"all-you-can-eat\" buffet and a Las Vegas tradition was born. Five years later, \"Bugsy\" Siegel and his mob affiliates opened the Flamingo Resort on the Strip. It was the first Las Vegas resort to combine a luxury hotel name, entertainment, and gambling, and was to become the prototype for the lavish Las Vegas casino-resort in the 1950s.\n\nVegas in the 1950s\n\nThe Flamingo was followed by the Sahara, the Sands, the Tropicana, the Showboat, the Riviera, and several other casino resorts. By 1954, over 8 million people were visiting Las Vegas each year, drawn by the lavish resort and name entertainers as much as by the gambling. Top performers, such as Elvis Presley, Frank Sinatra, Bing Crosby, and Dean Martin played in intimate cabaret-style theaters.\n\nThe 1950s was also the era of nuclear arms testing in Nevada. Between 1951 and 1963, the Atomic Energy Commission detonated over 100 explosions. Despite the dangers (largely ignored and underplayed at the time), many casinos promoted the tests as tourist attractions and even built \"sky rooms\" from which to view the mushroom clouds.\n\nThe 50s also saw the city of Las Vegas develop from a casino town to a functioning city. McCarran Airport was built in 1948; The University of Las Vegas was established in 1957; and the Las Vegas Convention Center opened in 1959. By 1960, Las Vegas had a permanent population of over 64,000.\n\nHoward Hughes and the 1960s\n\nMany of the early Las Vegas casinos, such as \"Bugsy\" Siegel''s Flamingo Hotel, had ties to, and received financing from, organized crime syndicates from the Midwest and East Coast. In the 1960s, this began to change. Corporations, led by the example of Howard Hughes'' acquisition of the Desert Inn, started seeing Las Vegas casinos as legitimate business ventures. By the end of the decade, organized crime was all but out of the gaming business.\n\nSteve Wynn, the 80s, and 90s\n\nThe opening of Steve Wynn''s 3300-room Mirage Resort on the Strip in 1989 ushered in a new era of Las Vegas resorts. Gone and going were the simple gambling halls in favor of huge theme resorts, complete with resident attractions, headliners, and elegant restaurants as well as casinos. Funding for these mega-resorts was unique also. The Mirage was the first resort to be constructed with a junk bond offering. The free volcano attraction in front of the hotel as well as the resident Siegfried and Roy show became the model for Las Vegas resorts in the 1990s.\n\nThe city of Las Vegas boomed also. By 1995, the city''s population had skyrocketed to over 350,000 residents, spurred by an incredible 9 percent annual increase in jobs. Downtown Las Vegas also experienced a renaissance in the 1990s. Fremont Street transformed itself in 1995 into a pedestrian mall, enclosed by a 90-foot high domed screen onto which an elaborate sound and light show is projected every hour after dark. The area also boasts street performers, interesting shopping, and frequent free concerts.\n\nTo make more room for the new generation of Las Vegas resorts, developers began imploding, or blowing up, the old 1950s-style hotels and erecting new resort palaces in their ashes. Such was the fate of the Dunes, the present site of the Bellagio Hotel & Casino; the Sands, the present site of the Venetian Resort; and the original Aladdin Hotel in favor of the new Planet Hollywood Resort & Casino.\n\nLas Vegas Today\n\nLas Vegas today offers something for visitors of all ages. In addition to the lavish casinos, the city boasts theme parks, some of the nation''s best restaurants, elaborate pool complexes, and one-of-a-kind shopping arcades. Over 34.7 million travelers visited Las Vegas in 2005."}]'::jsonb)
on conflict (id) do nothing;

update public.tests set passages = '[{"id": "cjsd", "category": "Чтение", "title": "Jobs: Creative Job Speed Dating", "text": "JOBS: CREATIVE JOB SPEED DATING\n\n\"OK ladies and gentlemen, let''s begin, you have 5 minutes starting now.\"\n\nWe were seated at a long black table in a 16th-floor suite at Sofitel Vienna Stephansdom. The five pairs engaged in conversation, asking questions, writing notes on carbon paper.\n\nI \"dated\" a food editor for Woman Magazine, an editor at a corporate publishing start-up, Managing Editor of the business magazine Format, a consultant at a corporate branding company and a recently unemployed advertising salesman, all in 25 minutes.\n\nCreative Job Speed Dating (CJSD) is the brainchild of interior and set designer Rikki Wieland, and fashion and advertising photographer Michael Dürr. They had invited mostly members of the press and PR community to this third session.\n\nThe idea grew out of Dürr''s birthday party in early 2013, where he had set up a room for traditional speed dating. While guests did seem to enjoy themselves and it served as a fast track for his friends and colleagues to get to know each other, those who were spoken for felt wary about joining in.\n\nBut they had plenty of reasons to talk, and so the idea for quickie \"dating\" for creative professionals was born.\n\nThe classic idea behind speed dating is a series of brief encounters: encapsulated life stories, informing, and perchance enticing the conversation partner in all of 5 minutes.\n\nAs freelancers, most people in the creative industry rely greatly on networking, but not everyone has the time or energy to go to event after event, hoping to strike up a helpful conversation. CJSD aims to make this easier. Some were sceptical about the idea at the Sofitel event in June, but then again, how bad could it be?\n\nThe worst that can happen is that you spend a few minutes talking to someone you''ll never work with. And the best case scenario can be a new job or project, or simply inspiration. So far, the \"speed dating\" events have drawn between 20 and 80 people.\n\nSome call it \"working the room\" – roaming around, introducing yourself and striking up conversations. While perhaps pushy, this is a necessary evil as a creative freelancer. In the CJSD setting, it is not crass to brag about ideas or projects you are proud of.\n\nEven asking professionally \"personal\" questions like \"how much does that cost?\" or \"how much does your company rely on ad revenue?\" is normal, even expected.\n\nIn the \"waiting room\", invitees said they actually got pitches for projects and ways to cooperate, simply because that''s what they were there for.\n\nIn September and October the team will be inviting fashion professionals to a Vienna-fashion-week-themed event, and in October it''s all about art, as Vienna is taken over by the VIENNAFAIR. So if you''re a designer, makeup artist, or fashion photographer – keep checking CJSD''s Facebook page for future dates and venues."}, {"id": "immigrants", "category": "Чтение", "title": "Three young immigrants", "text": "SAYEED\n\nMy father left Palestine when the war started and fled to Kuwait. He met my mother there, although she''s English, and I was born there. They sent me to school in England when I was 10, which I quite enjoyed. It was vastly different from life in Kuwait; there were so many rules and it seemed so alien to me. But I tried hard to fit in. We spoke English at home, so the language wasn''t a problem when I came to England. Nowadays I wish I had learnt Arabic while I was little, and not been so against learning it. I had a private tutor, but I''m afraid I was a horrible pupil. One day I really upset him so he wouldn''t come back and teach me any more!\n\nIt would have been nice to speak two languages fluently, but I think I''m not really talented as far as languages go. I''m hopeless at French, in spite of learning it for years at school.\n\nWhat I miss about life in Kuwait is the big family gatherings. There''s much more to family life than in England. But I like the freedom you have here too. Too much family can get annoying.\n\nI love Arabic food and I suppose I just copied my dad when it came to eating Arabic style. My brother and sister and I were not like typical Kuwaiti kids and he would always joke about us being \"weak from the English side\", although I know he was very proud of us too.\n\nIf I have a family I would want my children to belong to both cultures. I think it''s important not to deny your origins, and to continue being Palestinian. I think of myself as a \"double-caste\" not a \"half-caste\"!\n\nDuring the Gulf War I felt threatened, a bit less confident. But apart from some bad experiences when some people reacted badly to me, I''ve never been discriminated against. The only racist experiences I''ve had were in my head. In fact London especially is a very tolerant place. I like the way the English are straight with you, they don''t like airs and graces. They can be a bit conservative for my liking, and I can''t stand being patronised by some of them. But the variety of cultures is great, it makes London a great place to live in.\n\nMAIKA\n\nI came from Poland in 1989. It was quite unstable there then and life here in England seemed much easier. I was married to an Englishman and he was brought back here by his company. There are lots of differences, for example there''s a bigger variety of food here, with the Indian and Chinese restaurants, and so on. I had learnt English in school, but when I got here it wasn''t the same. Some accents, like cockney, are so difficult to understand!\n\nApart from my family and friends I don''t really feel I''m missing very much. It''s important to keep in touch and I do mix with Poles when I can. If I have children I want them to learn Polish and keep up the cultural traditions. Families in Poland are much closer than in Britain. I was amazed how some people here don''t see their sisters or brothers ever! In Poland it is more like it used to be here. They take care of the old people and there''s more discipline. Families help each other more.\n\nPeople here in England dress more casually, different than in Poland. They don''t care what they look like. But I enjoy the differences. The British are very tolerant and friendly. I''ll always be Polish, I think it''s impossible to change deep down, and I don''t see any advantage in changing.\n\nMAI HUA TA\n\nMy grandmother was one of the \"Boat People\" who left Vietnam in little boats to get away from persecution. We immigrated to Britain later when I was only seven. My grandmother came to the airport to meet us with loads of jackets, it was so cold. I''ll always remember seeing English people for the first time. Their hair is so colourful! And compared to us they are so big.\n\nIt was easy for me and my brother to learn English but my parents still don''t speak good English. They can get by in everyday situations but can''t really converse properly.\n\nMy mum still can''t use a knife and fork properly, but we children soon got used to everything. I''d never seen cheese before, and apples and grapes were very strange too.\n\nWe are ethnically Chinese, not Vietnamese, and in our tradition the old people are treated with a lot of respect. I want my children to learn that too, because after all, I''m going to be old one day too.\n\nI don''t want to go back to Vietnam. There''s a lot of corruption there and I''ve heard of people having to pay the police to stop them making trouble for them. My mum misses being with Chinese people but I find it better here. The standard of living is much higher, though I miss the family closeness, and some of the food.\n\nThe older generation Chinese people are very strict with the young people. You are not supposed to kiss your boyfriend, or even hold hands in public. There''s too much gossip. I don''t mix with the Chinese much. There''s more freedom here. I like the British, I like their openness, and they are more straightforward than the Chinese. But I want my children to learn Chinese, I want the best of both cultures."}, {"id": "vegas", "category": "Чтение", "title": "History of Las Vegas", "text": "HISTORY OF LAS VEGAS\n\nThe first Las Vegas Strip hotel, the El Rancho, opened in 1941. It became famous for its \"all-you-can-eat\" buffet and a Las Vegas tradition was born. Five years later, \"Bugsy\" Siegel and his mob affiliates opened the Flamingo Resort on the Strip. It was the first Las Vegas resort to combine a luxury hotel name, entertainment, and gambling, and was to become the prototype for the lavish Las Vegas casino-resort in the 1950s.\n\nVegas in the 1950s\n\nThe Flamingo was followed by the Sahara, the Sands, the Tropicana, the Showboat, the Riviera, and several other casino resorts. By 1954, over 8 million people were visiting Las Vegas each year, drawn by the lavish resort and name entertainers as much as by the gambling. Top performers, such as Elvis Presley, Frank Sinatra, Bing Crosby, and Dean Martin played in intimate cabaret-style theaters.\n\nThe 1950s was also the era of nuclear arms testing in Nevada. Between 1951 and 1963, the Atomic Energy Commission detonated over 100 explosions. Despite the dangers (largely ignored and underplayed at the time), many casinos promoted the tests as tourist attractions and even built \"sky rooms\" from which to view the mushroom clouds.\n\nThe 50s also saw the city of Las Vegas develop from a casino town to a functioning city. McCarran Airport was built in 1948; The University of Las Vegas was established in 1957; and the Las Vegas Convention Center opened in 1959. By 1960, Las Vegas had a permanent population of over 64,000.\n\nHoward Hughes and the 1960s\n\nMany of the early Las Vegas casinos, such as \"Bugsy\" Siegel''s Flamingo Hotel, had ties to, and received financing from, organized crime syndicates from the Midwest and East Coast. In the 1960s, this began to change. Corporations, led by the example of Howard Hughes'' acquisition of the Desert Inn, started seeing Las Vegas casinos as legitimate business ventures. By the end of the decade, organized crime was all but out of the gaming business.\n\nSteve Wynn, the 80s, and 90s\n\nThe opening of Steve Wynn''s 3300-room Mirage Resort on the Strip in 1989 ushered in a new era of Las Vegas resorts. Gone and going were the simple gambling halls in favor of huge theme resorts, complete with resident attractions, headliners, and elegant restaurants as well as casinos. Funding for these mega-resorts was unique also. The Mirage was the first resort to be constructed with a junk bond offering. The free volcano attraction in front of the hotel as well as the resident Siegfried and Roy show became the model for Las Vegas resorts in the 1990s.\n\nThe city of Las Vegas boomed also. By 1995, the city''s population had skyrocketed to over 350,000 residents, spurred by an incredible 9 percent annual increase in jobs. Downtown Las Vegas also experienced a renaissance in the 1990s. Fremont Street transformed itself in 1995 into a pedestrian mall, enclosed by a 90-foot high domed screen onto which an elaborate sound and light show is projected every hour after dark. The area also boasts street performers, interesting shopping, and frequent free concerts.\n\nTo make more room for the new generation of Las Vegas resorts, developers began imploding, or blowing up, the old 1950s-style hotels and erecting new resort palaces in their ashes. Such was the fate of the Dunes, the present site of the Bellagio Hotel & Casino; the Sands, the present site of the Venetian Resort; and the original Aladdin Hotel in favor of the new Planet Hollywood Resort & Casino.\n\nLas Vegas Today\n\nLas Vegas today offers something for visitors of all ages. In addition to the lavish casinos, the city boasts theme parks, some of the nation''s best restaurants, elaborate pool complexes, and one-of-a-kind shopping arcades. Over 34.7 million travelers visited Las Vegas in 2005."}]'::jsonb where id = 'epe-sample-1';

