  ('epe-sample-1-rc1', 'epe-sample-1', 1, 'Чтение', 'tf_table',
   'SAMPLE TASK FOR TRUE/FALSE/JUSTIFICATION (10 points). Read the text about "Creative job speed dating". First decide if the statements 1-10 are true (T) or false (F). Then identify the sentence in the text which supports your decision and write the first four words of that sentence.',
   'cjsd', '{"rows": [{"id": "0", "statement": "Rikki Wieland and Michael Dürr invented \"Creative Job Speed Dating\".", "correct": true, "words": ["Creative", "Job", "Speed", "Dating"], "isExample": true}, {"id": "1", "statement": "At a private event, Dürr had arranged a romantic speed dating.", "correct": true, "words": ["The", "idea", "grew", "out"]}, {"id": "2", "statement": "CJSD allows you to talk to five different people in less than half an hour.", "correct": true, "words": ["I", "dated", "a", "food"]}, {"id": "3", "statement": "\"Creative Job Speed Dating\" at Sofitel Vienna Stephansdom was the first of its kind.", "correct": false, "words": ["They", "had", "invited", "mostly"]}, {"id": "4", "statement": "All freelancers have a lot of free time and can easily attend a lot of events.", "correct": false, "words": ["As", "freelancers,", "most", "people"]}, {"id": "5", "statement": "The Sofitel event took place in autumn.", "correct": false, "words": ["Some", "were", "sceptical", "about"]}, {"id": "6", "statement": "The risk you take when attending a \"Creative Job Speed Dating\" event is not very high.", "correct": true, "words": ["The", "worst", "that", "can"]}, {"id": "7", "statement": "As a creative freelancer you have to be pushy.", "correct": true, "words": ["While", "perhaps", "pushy,", "this"]}, {"id": "8", "statement": "It is taboo to ask questions about money.", "correct": false, "words": ["Even", "asking", "professionally", "personal"]}, {"id": "9", "statement": "All invitees hope to find an employment.", "correct": false, "words": ["In", "the", "waiting", "room"]}, {"id": "10", "statement": "There will be more CJSD events in Vienna.", "correct": true, "words": ["In", "September", "and", "October"]}]}'::jsonb)
on conflict (id) do nothing;

