   'immigrants', '[{"id": "0", "label": "0. was born in Kuwait.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "sayeed", "isExample": true}, {"id": "1", "label": "1. found that the English which people spoke was not like the English taught in school.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "maika"}, {"id": "2", "label": "2. doesn''t want to return to his/her country of birth.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "maihuata"}, {"id": "3", "label": "3. found the English weather very cold at first.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "maihuata"}, {"id": "4", "label": "4. says people in England don''t care that much about their clothes.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "maika"}, {"id": "5", "label": "5. didn''t know how to use cutlery.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "maihuata"}, {"id": "6", "label": "6. can speak only English fluently.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "sayeed"}, {"id": "7", "label": "7. misses the food from his/her native country.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "maihuata"}, {"id": "8", "label": "8. thinks the British tend to be conservative.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "sayeed"}, {"id": "9", "label": "9. finds some aspects of family life better in Britain.", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "sayeed"}, {"id": "10", "label": "10. Whose family doesn''t live in England?", "type": "single_choice", "options": [{"id": "sayeed", "text": "Sayeed"}, {"id": "maika", "text": "Maika"}, {"id": "maihuata", "text": "Mai Hua Ta"}], "correctOptionId": "maika"}]'::jsonb)
