  ('epe-sample-1-rc4', 'epe-sample-1', 4, 'Чтение', 'multi_part',
   'SAMPLE TASK FOR MULTIPLE CHOICE (6 points). Read the text about how Las Vegas has developed over the years, then choose the correct answer (A, B, C or D) for questions 1-6.',
   'vegas', '[{"id": "0", "label": "0. The Flamingo Resort", "type": "single_choice", "options": [{"id": "A", "text": "was the most luxurious casino in the 1940s."}, {"id": "B", "text": "focused mainly on light entertainment."}, {"id": "C", "text": "offered all-inclusive package holidays."}, {"id": "D", "text": "was the first of its kind."}], "correctOptionId": "D", "isExample": true}, {"id": "1", "label": "1. In the 1950s show business celebrities", "type": "single_choice", "options": [{"id": "A", "text": "performed to small audiences."}, {"id": "B", "text": "visited Las Vegas in huge numbers."}, {"id": "C", "text": "concentrated on comedy mainly."}, {"id": "D", "text": "always stayed in luxury hotels."}], "correctOptionId": "A"}, {"id": "2", "label": "2. The testing of nuclear weapons in the 1950s", "type": "single_choice", "options": [{"id": "A", "text": "was viewed by huge numbers of tourists."}, {"id": "B", "text": "furthered the development of atomic war technology."}, {"id": "C", "text": "triggered the public''s interest in atomic energy."}, {"id": "D", "text": "was advertised in order to draw visitors to Las Vegas."}], "correctOptionId": "D"}, {"id": "3", "label": "3. In the 1960s, Las Vegas casinos", "type": "single_choice", "options": [{"id": "A", "text": "became the centre of large-scale money transactions."}, {"id": "B", "text": "had to close down due to criminal activities."}, {"id": "C", "text": "were eventually regarded as lawful enterprises."}, {"id": "D", "text": "had to cope with the pressures of competing businesses."}], "correctOptionId": "C"}, {"id": "4", "label": "4. Steve Wynn''s Mirage Resort", "type": "single_choice", "options": [{"id": "A", "text": "quickly became the most popular casino on the Strip."}, {"id": "B", "text": "set new standards for future Las Vegas resorts."}, {"id": "C", "text": "offered fine dining for hotel guests only."}, {"id": "D", "text": "was the first hotel to put on spectacular nightly entertainment."}], "correctOptionId": "B"}, {"id": "5", "label": "5. In the 1990s the city centre of Las Vegas", "type": "single_choice", "options": [{"id": "A", "text": "was upgraded with a few high-tech cinemas."}, {"id": "B", "text": "attracted the entertainment industry."}, {"id": "C", "text": "became much more lively."}, {"id": "D", "text": "offered hourly outdoor laser shows throughout the day."}], "correctOptionId": "C"}, {"id": "6", "label": "6. A number of modern luxury hotels were built", "type": "single_choice", "options": [{"id": "A", "text": "along the most attractive stretches of the Strip."}, {"id": "B", "text": "in an environmentally friendly way."}, {"id": "C", "text": "to appeal mainly to the younger visitors."}, {"id": "D", "text": "on the sites of the old hotels."}], "correctOptionId": "D"}]'::jsonb)
on conflict (id) do nothing;

