insert into public.tests
  (id, exam_key, title, short_description, full_description, is_official, topic, format, year, duration_minutes, oral_task)
values
  ('epe-oral-sample-1', 'epe', 'EPE Sample Oral Exam (Sept 2024)',
   'Официальный образец устного экзамена EPE — выбор одной из двух тем, подготовка ~20 минут, обсуждение с экзаменатором ~7 минут.',
   'Официальный образец устного экзамена EPE от VWU (по состоянию на сентябрь 2024). Две темы на выбор — каждая с парой контрастных фотографий и тремя наводящими вопросами (Part A / Part B).',
   true, 'nutrition', 'oral', 2024, 30,
   '{"stages": [{"id": "speaking", "title": "Speaking Task", "kind": "choice", "instructions": "Choose one of the two topics below. Contrast the two pictures, then answer the guiding questions — you''ll discuss this with your examiner for about 7 minutes.", "prepMinutes": 20, "options": [{"id": "sample1", "label": "Sample 1: Hobbies and free-time activities and celebrating special events", "kind": "image", "image": "epe-oral-sample-1", "leitfragen": ["Part A — Contrast the pictures.", "Part B — Evaluate the importance of special events and traditions for young people.", "Part B — Speculate how traditions might change in the future."]}, {"id": "sample2", "label": "Sample 2: Hobbies and free-time activities and celebrating special events", "kind": "image", "image": "epe-oral-sample-2", "leitfragen": ["Part A — Contrast the pictures.", "Part B — Explain what makes movies attractive.", "Part B — Suggest ways to encourage young people to go to the theatre."]}]}]}'::jsonb)
