   'kakaoplantagen', '[{"id": "1", "label": "1. Welche konkreten Maßnahmen wurden von Süßwarenhändlern gegen Kinderarbeit getroffen?", "type": "free_text", "hint": "Antworten Sie in Stichwörtern — kein ganzer Satz nötig.", "sampleAnswer": "Millionen Euro in Entwicklungsprogramme pumpen; Bauern helfen, ihre Produktion zu steigern; Schulen bauen."}, {"id": "2", "label": "2. Wie kann Kinderarbeit bei den Kakaoproduzenten vermieden werden?", "type": "free_text", "hint": "Antworten Sie in Stichwörtern — kein ganzer Satz nötig.", "sampleAnswer": "Die Kaufkraft der Bauern erhöhen, damit sie in ihre Plantagen investieren und arbeitsrechtliche Vorschriften befolgen können."}, {"id": "3", "label": "3. Warum verdienen die Kakaobauern trotz des hohen Preises für Kakao so wenig?", "type": "free_text", "hint": "Antworten Sie in Stichwörtern — kein ganzer Satz nötig.", "sampleAnswer": "Kakao wird nicht großflächig angebaut; die Bauern haben keine Verhandlungsmacht; die Bauern erhalten nur einen Bruchteil des Preises."}, {"id": "4", "label": "4. Was versprechen die großen Süßwarenhersteller?", "type": "free_text", "hint": "Antworten Sie in Stichwörtern — kein ganzer Satz nötig.", "sampleAnswer": "Kampf gegen Kinderarbeit / Kinderarbeit reduzieren; strukturelle Änderungen im Kakaoanbau und -handel."}]'::jsonb)
