   '{"rows": [{"id": "1", "prompt": "1. Die Werbung arbeitet mit vielen Tricks,", "freeText": true}, {"id": "2", "prompt": "2. Zwar geben die Eltern das Geld aus,", "freeText": true}, {"id": "3", "prompt": "3. Firmen, die den sanften Druck der Kinder auf die Kaufentscheidung der Eltern ignorieren,", "freeText": true}, {"id": "4", "prompt": "4. Je mehr Geld die Firmen in Produktforschung investieren,", "freeText": true}, {"id": "5", "prompt": "5. Sowohl durch Informationen", "freeText": true}, {"id": "6", "prompt": "6. Zwar wissen die Konsumenten, dass sie durch die Werbung manipuliert werden,", "freeText": true}, {"id": "7", "prompt": "7. Obwohl Kunden oft genau wissen, was sie kaufen wollen,", "freeText": true}, {"id": "8", "prompt": "8.", "freeText": true, "after": ", wird auch die Umwelt immer mehr belastet."}, {"id": "9", "prompt": "9. Viele Kunden denken,", "freeText": true}, {"id": "10", "prompt": "10. Wer von sich behauptet, dass er nicht von der Werbung beeinflusst wird,", "freeText": true}]}'::jsonb)
